const req = $('Normalize Request').first().json;
const tz = 'America/Chicago';
const day = DateTime.fromISO(req.date || '', { zone: tz });
if (!day.isValid) {
  return [{ json: { available_slots: [], result: 'I could not read that date. Ask the caller which day they want, then try again.' } }];
}
const events = $input.all().map(i => i.json).filter(e => e && e.start && e.status !== 'cancelled');
const allDayBlocked = events.some(e => e.start.date && !e.start.dateTime);
const busy = events.filter(e => e.start.dateTime && e.end && e.end.dateTime).map(e => ({ s: DateTime.fromISO(e.start.dateTime), e: DateTime.fromISO(e.end.dateTime) }));
const now = DateTime.now().setZone(tz);
const slotMinutes = 30;
const open = day.set({ hour: 9, minute: 0, second: 0, millisecond: 0 });
const close = day.set({ hour: 17, minute: 0, second: 0, millisecond: 0 });
const slots = [];
const isWeekday = day.weekday <= 5;
if (isWeekday && !allDayBlocked) {
  for (let s = open; s.plus({ minutes: slotMinutes }) <= close; s = s.plus({ minutes: slotMinutes })) {
    const e = s.plus({ minutes: slotMinutes });
    if (s <= now) continue;
    if (busy.some(b => s < b.e && e > b.s)) continue;
    slots.push({ start_time: s.toISO({ suppressMilliseconds: true }), label: s.toFormat('h:mm a') });
  }
}
const dayLabel = day.toFormat('cccc, LLLL d');
const result = slots.length
  ? 'Open 30-minute start times on ' + dayLabel + ' (Central Time): ' + slots.map(x => x.label).join(', ') + '. Offer two or three of these, spread out. Use the matching start_time when booking.'
  : 'No openings on ' + dayLabel + '. Offer the caller another weekday.';
return [{ json: { date: req.date, timezone: tz, available_slots: slots, result } }];
